function App() {
  const [renderedAt, setRenderedAt] = useState(() => new Date().toLocaleTimeString());
  const [count, setCount] = useState(1);
  const request = () => {
    setRenderedAt(new Date().toLocaleTimeString());
    setCount((c) => c + 1);
  };
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <h3>SSR: fresh on every request</h3>
      <p>Request #{count} rendered at <b>{renderedAt}</b></p>
      <button onClick={request}>Simulate a new request</button>
      <p style={{ fontSize: 12, color: '#666' }}>Each request re-renders with current data (here, the time).</p>
    </div>
  );
}

function App() {
  // Illustrative — these are server-side ways to trigger SSR in Next.js:
  const lines = [
    "await fetch(url, { cache: 'no-store' })   // uncached fetch -> SSR",
    "cookies().get('session')                  // dynamic function -> SSR",
    "headers().get('user-agent')               // dynamic function -> SSR",
    "export const dynamic = 'force-dynamic'    // explicit route config -> SSR",
  ];
  return (
    <pre style={{ fontFamily: 'ui-monospace, monospace', padding: 16, fontSize: 12 }}>
      {lines.join('\n')}
    </pre>
  );
}

