// Fixed: reading cookies() makes the route dynamic (SSR), so each request
// renders the correct user. Rendered here as illustrative text.
function App() {
  const code = [
    "import { cookies } from 'next/headers';",
    'export default async function Page() {',
    "  const session = cookies().get('session')?.value; // dynamic -> SSR",
    "  const user = await fetch('/api/me', {",
    "    cache: 'no-store',",
    "    headers: { cookie: 'session=' + session },",
    '  }).then(r => r.json());',
    '  return <h1>Hello, {user.name}</h1>;',
    '}',
  ];
  return (
    <pre style={{ fontFamily: 'ui-monospace, monospace', padding: 16, fontSize: 12 }}>
      {code.join('\n')}
    </pre>
  );
}

// app/account/page.tsx — Server Component (renders per request)
import { cookies } from 'next/headers';

export default async function AccountPage() {
  // Reading cookies() is a dynamic function -> route renders on the server per request (SSR)
  const session = cookies().get('session')?.value;

  const user = await fetch('https://api.example.com/me', {
    cache: 'no-store', // always fresh, never cached
    headers: { cookie: `session=${session ?? ''}` },
  }).then((r) => r.json());

  return (
    <main>
      <h1>Hello, {user.name}</h1>
      <p>You have {user.unreadCount} new notifications.</p>
    </main>
  );
}
